  snapshot(){return structuredClone({state:this.state,currentKnowledgeId:this.currentKnowledgeId,currentInstanceId:this.currentInstanceId,currentBoardId:this.currentBoardId,document:this.document,path:this.path})}
  restore(snapshot){this.state=snapshot.state;this.currentKnowledgeId=snapshot.currentKnowledgeId;this.currentInstanceId=snapshot.currentInstanceId;this.currentBoardId=snapshot.currentBoardId??null;this.document=snapshot.document;this.path=snapshot.path;this.selection.clear();this.fitPending=true;this.scheduleSave();this.renderAll()}
  undo(){const snapshot=this.undoStack.pop();if(!snapshot)return;this.redoStack.push(this.snapshot());this.restore(snapshot);this.hideUndoBanner()}
  redo(){const snapshot=this.redoStack.pop();if(!snapshot)return;this.undoStack.push(this.snapshot());this.restore(snapshot)}
  scheduleSave(reason='change'){$('#saveStatus').textContent='● 正在保存…';clearTimeout(this.saveTimer);this.saveTimer=setTimeout(async()=>{try{await replaceAll(this.state);$('#saveStatus').textContent=`● 已保存 ${new Date().toLocaleTimeString('zh-CN',{hour12:false})}`}catch(error){$('#saveStatus').textContent=`保存失败 · ${error.message}`}},240)}

  showUndoBanner(label){const names={'knowledge:delete':'知识已删除','structure:delete':'结构已删除','template:delete':'结构模板已删除','container:remove-content':'正文或引用已删除','container:clear':'容器内容已清空','binding:remove-all':'引用已移除','edge:remove':'关系已删除','slot:remove':'结构位置已删除'};$('#undoBannerText').textContent=names[label]??'内容已删除';$('#undoBanner').classList.remove('hidden');clearTimeout(this.undoBannerTimer);this.undoBannerTimer=setTimeout(()=>this.hideUndoBanner(),10000)}
  hideUndoBanner(){clearTimeout(this.undoBannerTimer);$('#undoBanner')?.classList.add('hidden')}
  closeOpenDialogs(except=null){for(const dialog of all('dialog[open]'))if(dialog!==except)dialog.close()}
  closeTransientOverlays(reason='navigation'){this.transient?.closeAll(reason);this.closeOpenDialogs()}

  get knowledge(){return this.state.knowledge.find(item=>item.id===this.currentKnowledgeId)}get instance(){return this.state.structureInstances.find(item=>item.id===this.currentInstanceId)}get template(){return this.state.structureTemplates.find(item=>item.id===this.instance?.templateId)}
  structureDisplayTitle(instance,template=this.state.structureTemplates.find(item=>item.id===instance?.templateId)){return String(instance?.displayTitle??localized(template?.nameI18n,this.preferences.language,template?.name??'Structure'))}
  templateName(template){return localized(template?.nameI18n,this.preferences.language,template?.name??'Structure')}
  templateBilingualName(template){const fallback=template?.name??'Structure',zh=localized(template?.nameI18n,'zh-CN',fallback),en=localized(template?.nameI18n,'en',fallback);return zh&&en&&zh!==en?`${zh} · ${en}`:zh||en||fallback}
  templateDescription(template){return localized(template?.descriptionI18n,this.preferences.language,template?.description??'')}
  effectiveSlotTitle(instance,slot){return getEffectiveTitle(slot,{kind:'slot',instance,state:this.state,container:instance?.containers?.[slot.id]})}
  openNewTab(){this.closeTransientOverlays();this.closePanel();this.document=`new-tab:${uid()}`;this.rememberDocument(this.currentKnowledgeId,this.document);this.path=this.knowledge?[knowledgeSegment(this.knowledge),{kind:'document',id:this.document,label:'新标签页',document:this.document}]:[{kind:'document',id:this.document,label:'新标签页',document:this.document}];this.pushLocation();this.renderAll()}
  runNewTabAction(action){if(action==='knowledge')return this.openQuickCreate(null,'blank');if(action==='lmn')return this.openQuickCreate(null,'lmn');if(action==='structure')return this.openLibrary();if(action==='notes')return this.knowledge?this.activateDocument('notes',true,this.currentKnowledgeId):this.openQuickCreate();if(action==='import')return this.openImport();if(action==='search')return this.openCommand()}
  requestText(title,value,onCommit,{label='名称',hint=''}={}){const dialog=$('#textPromptDialog'),input=$('#textPromptInput');$('#textPromptTitle').textContent=title;$('#textPromptLabel').firstChild.textContent=label;$('#textPromptHint').textContent=hint;input.value=value??'';this.textPromptAction=onCommit;dialog.showModal();requestAnimationFrame(()=>{input.focus();input.select()})}
  finishTextPrompt(){const dialog=$('#textPromptDialog'),action=this.textPromptAction;this.textPromptAction=null;if(dialog.returnValue!=='default'||!action)return;const value=$('#textPromptInput').value.trim();if(value)action(value)}
  openQuickCreate(bindingContext=null,mode='blank'){this.quickBind=bindingContext;this.setQuickCreateMode(mode);this.transient?.open('quickCreate');$('#quickCreateInput').value='';$('#quickCreateInput').focus()}closeQuickCreate(){this.transient?.close('quickCreate','cancel')}
  setQuickCreateMode(mode){this.quickCreateMode=mode==='lmn'?'lmn':'blank';all('[data-create-mode]').forEach(button=>button.classList.toggle('active',button.dataset.createMode===this.quickCreateMode))}
  createKnowledgeFromQuick(){const title=$('#quickCreateInput').value.trim();if(!title)return;this.closeQuickCreate();this.createKnowledge(title,{withLmn:this.quickCreateMode==='lmn'})}
