    if(!modular){this.field(grid,'图标',variable.icon??'',value=>this.updateVariableAction(variable.id,{icon:value}));this.field(grid,'颜色',variable.color??'#7657A8',value=>this.updateVariableAction(variable.id,{color:value}),{type:'color'});this.field(grid,'显示在结构中',variable.showOnCanvas===false?'false':'true',value=>this.updateVariableAction(variable.id,{showOnCanvas:value==='true'}),{options:[{value:'true',label:'显示'},{value:'false',label:'隐藏'}]})}const space=document.createElement('div');space.className='binding-explainer';space.innerHTML=`<b>结果空间</b><br>${escapeHtml(resultSpaceLabel(variable.resultSpace??this.instance.resultSpace??this.currentDefinition?.resultSpace,{...this.instance.parameters,...this.instance.runtimeState.variables}))}<br><small>公式只描述计算；结果由结构空间统一归一化。</small>`;detail.append(space);
