  openPicker(slotId,nestedOnly=false,placementMode='construct'){this.pendingSlotId=slotId;this.pickerNestedOnly=nestedOnly;this.pendingPlacementMode=placementMode==='reference'?'reference':'construct';$('#pickerTitle').textContent=this.pendingPlacementMode==='reference'?'引用已有知识':'构造知识坐标';$('#pickerSearch').value='';this.renderPicker();$('#pickerDialog').showModal();setTimeout(()=>$('#pickerSearch').focus(),50)}
  renderPicker(){const root=$('#pickerResults'),query=$('#pickerSearch').value.trim().toLowerCase();root.replaceChildren();if(!this.pickerNestedOnly)for(const knowledge of this.state.knowledge.filter(item=>!query||`${item.title} ${item.summary??''}`.toLowerCase().includes(query))){const row=document.createElement('button');row.className='picker-row';row.innerHTML=`<span>◇</span><span>${escapeHtml(knowledge.title)}</span><small>Knowledge</small>`;row.onclick=()=>this.bindSelection('knowledge',knowledge.id);root.append(row)}for(const instance of this.state.structureInstances.filter(item=>item.id!==this.currentInstanceId)){const template=this.state.structureTemplates.find(item=>item.id===instance.templateId);if(query&&!template?.name.toLowerCase().includes(query))continue;const row=document.createElement('button');row.className='picker-row';row.innerHTML=`<span>⬡</span><span>${escapeHtml(template?.name)}</span><small>Structure</small>`;row.onclick=()=>this.bindSelection('structure',instance.id);root.append(row)}}
