  renderCommands(){const root=$('#commandResults'),items=this.commandItems();this.commandIndex=Math.min(this.commandIndex,Math.max(0,items.length-1));root.replaceChildren();for(const[category,commands]of groupCommands(items)){const group=document.createElement('section');group.className='command-group';group.innerHTML=`<h3>${escapeHtml(category)}</h3>`;for(const item of commands){const index=items.indexOf(item),button=document.createElement('button');button.className='command-row';button.classList.toggle('active',index===this.commandIndex);button.classList.toggle('disabled',!item.enabled);button.setAttribute('aria-disabled',String(!item.enabled));button.innerHTML=`<span>${item.icon??'⌘'}</span><span>${escapeHtml(item.label)}<small>${escapeHtml(item.enabled?item.labelEn??'':item.disabledReason)}</small></span><kbd>${escapeHtml(item.slash??'')}</kbd>`;button.onclick=()=>this.executeCommand(item);group.append(button)}root.append(group)}if(!items.length)root.innerHTML='<p class="command-empty">没有匹配命令</p>'}
  commandKeys(event){const items=this.commandItems();if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();const direction=event.key==='ArrowDown'?1:-1;if(items.length){let next=this.commandIndex;do next=(next+direction+items.length)%items.length;while(!items[next].enabled&&next!==this.commandIndex);this.commandIndex=next;this.renderCommands()}}if(event.key==='Enter'&&items[this.commandIndex]){event.preventDefault();this.executeCommand(items[this.commandIndex])}}
