  openQuickBuilder(){const library=$('#structureLibrary');if(library.open)library.close();this.quickBuilderDraft={nodes:[{id:'node-1',label:'节点 1',role:'custom',x:110,y:110},{id:'node-2',label:'节点 2',role:'custom',x:350,y:110},{id:'node-3',label:'节点 3',role:'custom',x:230,y:260}],edges:[{id:'relation-1',sourceSlotId:'node-1',targetSlotId:'node-2',direction:'directed',label:'关系'}],selected:{kind:'node',id:'node-1'}};this.quickBuilderLinkMode=false;this.quickBuilderLinkSource=null;this.renderQuickBuilder();$('#quickBuilderDialog').showModal();$('#builderName').focus()}
