  renderQuickBuilder(){const draft=this.quickBuilderDraft,canvas=$('#builderVisualCanvas'),inspector=$('#builderVisualInspector');if(!draft||!canvas)return;canvas.replaceChildren();const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 640 420');svg.classList.add('visual-builder-edges');canvas.append(svg);for(const edge of draft.edges){const source=draft.nodes.find(item=>item.id===edge.sourceSlotId),target=draft.nodes.find(item=>item.id===edge.targetSlotId);if(!source||!target)continue;const line=document.createElementNS('http://www.w3.org/2000/svg','line');line.dataset.edgeId=edge.id;line.setAttribute('x1',source.x+60);line.setAttribute('y1',source.y+34);line.setAttribute('x2',target.x+60);line.setAttribute('y2',target.y+34);line.setAttribute('marker-end','url(#builder-arrow)');line.classList.toggle('selected',draft.selected?.kind==='edge'&&draft.selected.id===edge.id);line.onclick=()=>{draft.selected={kind:'edge',id:edge.id};this.renderQuickBuilder()};svg.append(line)}const defs=document.createElementNS('http://www.w3.org/2000/svg','defs');defs.innerHTML='<marker id="builder-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0L10 5L0 10Z"/></marker>';svg.prepend(defs);const repaintEdges=()=>{for(const edge of draft.edges){const source=draft.nodes.find(item=>item.id===edge.sourceSlotId),target=draft.nodes.find(item=>item.id===edge.targetSlotId),line=svg.querySelector(`[data-edge-id="${CSS.escape(edge.id)}"]`);if(!source||!target||!line)continue;line.setAttribute('x1',source.x+60);line.setAttribute('y1',source.y+34);line.setAttribute('x2',target.x+60);line.setAttribute('y2',target.y+34)}};for(const node of draft.nodes){const button=document.createElement('button');button.className='visual-builder-node';button.classList.toggle('selected',draft.selected?.kind==='node'&&draft.selected.id===node.id);button.classList.toggle('link-source',this.quickBuilderLinkSource===node.id);button.style.left=`${node.x}px`;button.style.top=`${node.y}px`;button.innerHTML=`<b>${escapeHtml(node.label)}</b><small>${escapeHtml(node.role)}</small>`;button.onclick=()=>this.selectQuickBuilderNode(node);button.onpointerdown=event=>{if(event.button!==0)return;const start={x:event.clientX,y:event.clientY,nodeX:node.x,nodeY:node.y};button.setPointerCapture(event.pointerId);const move=next=>{if(Math.hypot(next.clientX-start.x,next.clientY-start.y)<3)return;node.x=Math.max(0,Math.min(520,start.nodeX+next.clientX-start.x));node.y=Math.max(0,Math.min(340,start.nodeY+next.clientY-start.y));button.style.left=`${node.x}px`;button.style.top=`${node.y}px`;repaintEdges()},end=next=>{if(button.hasPointerCapture(next.pointerId))button.releasePointerCapture(next.pointerId);button.removeEventListener('pointermove',move);button.removeEventListener('pointerup',end)};button.addEventListener('pointermove',move);button.addEventListener('pointerup',end)};canvas.append(button)}this.renderQuickBuilderInspector(inspector)}
  renderQuickBuilderInspector(inspector){const draft=this.quickBuilderDraft,selected=draft?.selected,source=selected?.kind==='node'?draft.nodes.find(item=>item.id===selected.id):draft?.edges.find(item=>item.id===selected?.id);if(!source){inspector.innerHTML='<p>选择节点或关系后可编辑。</p>';return}if(selected.kind==='node'){inspector.innerHTML=`<span class="eyebrow">NODE</span><h3>${escapeHtml(source.id)}</h3><label>标题<input name="label" value="${escapeHtml(source.label)}"></label><label>语义角色<input name="role" value="${escapeHtml(source.role)}"></label>`;for(const input of inspector.querySelectorAll('input'))input.oninput=()=>{source[input.name]=input.value;const button=$('#builderVisualCanvas').querySelectorAll('.visual-builder-node')[draft.nodes.indexOf(source)];if(button)button.querySelector(input.name==='label'?'b':'small').textContent=input.value}}else{inspector.innerHTML=`<span class="eyebrow">RELATION</span><h3>${escapeHtml(source.sourceSlotId)} → ${escapeHtml(source.targetSlotId)}</h3><label>关系名称<input name="label" value="${escapeHtml(source.label??'')}"></label><label>方向<select name="direction"><option value="directed">单向</option><option value="bidirectional">双向</option><option value="undirected">无向</option></select></label>`;inspector.querySelector('select').value=source.direction;for(const input of inspector.querySelectorAll('input,select'))input.oninput=()=>source[input.name]=input.value}}
  saveQuickTemplate(){const name=$('#builderName').value.trim(),draft=this.quickBuilderDraft;if(!name||!draft?.nodes.length)return;const template={id:`custom:${uid()}`,name,description:'由可视化结构构建器创建；可继续使用 LKL 1 编辑任意高级结构。',version:1,category:$('#builderCategory').value,builtin:false,nestable:true,computable:false,slots:draft.nodes.map((node,index)=>({id:node.id,label:node.label,role:node.role,semanticCoordinate:{order:index},accepts:['knowledge','structure','value','variable'],cardinality:'many'})),edges:draft.edges.map(edge=>({...edge,relationType:'related',routing:'straight'})),parameters:[],variables:[],constraints:[],rules:[],layout:{type:'manual',positions:Object.fromEntries(draft.nodes.map(node=>[node.id,{x:node.x+40,y:node.y+60}]))},visual:{accent:'#596B63'}};this.state.structureTemplates.push(template);this.scheduleSave('template:create');$('#quickBuilderDialog').close();this.quickBuilderDraft=null;this.insertTemplate(template.id)}
