  renderAdvancedMiniScene(definition){const host=$('#advancedSummary'),parameters=Object.fromEntries((definition.parameters??[]).map(item=>[item.id,item.defaultValue])),previewInstance={id:'preview',parameters,variables:definition.variables??[],runtimeState:{variables:{},results:{},errors:{}},layoutState:{visualOffsets:{},nodePositions:{}},overrides:{addedSlots:[],removedSlotIds:[],addedEdges:[],removedEdgeIds:[],slotPatches:{},edgePatches:{}}},scene=buildSceneGeometry(definition,previewInstance),svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.classList.add('advanced-scene');svg.setAttribute('viewBox',`${scene.bounds.x} ${scene.bounds.y} ${scene.bounds.width} ${scene.bounds.height}`);for(const edge of scene.edges){const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',edge.path);svg.append(path)}for(const node of scene.nodes){const shape=document.createElementNS(svg.namespaceURI,node.shape==='circle'?'circle':'rect');if(node.shape==='circle'){shape.setAttribute('cx',node.x+node.width/2);shape.setAttribute('cy',node.y+node.height/2);shape.setAttribute('r',Math.min(node.width,node.height)/2)}else{shape.setAttribute('x',node.x);shape.setAttribute('y',node.y);shape.setAttribute('width',node.width);shape.setAttribute('height',node.height);shape.setAttribute('rx','10')}const text=document.createElementNS(svg.namespaceURI,'text');text.setAttribute('x',node.x+node.width/2);text.setAttribute('y',node.y+node.height/2+4);text.textContent=node.label;svg.append(shape,text)}host.append(svg)}
  saveAdvanced(){const result=this.validateAdvanced();if(!result.valid)return;const template={...result.definition,builtin:false,version:result.definition.version??1};const index=this.state.structureTemplates.findIndex(item=>item.id===template.id);if(index>=0)this.state.structureTemplates[index]=template;else this.state.structureTemplates.push(template);this.scheduleSave('template:lkl');$('#advancedBuilderDialog').close();this.insertTemplate(template.id)}
