  openKnowledgeMenu(knowledgeId,event){const rect=event.currentTarget.getBoundingClientRect(),placements=this.knowledgePlacements(knowledgeId);this.showContextMenu(rect.right-220,rect.bottom+4,[{icon:'✎',label:'重命名',action:()=>this.renameKnowledge(knowledgeId)},{icon:'◎',label:`查看全部出现位置 (${placements.length})`,action:()=>this.openKnowledgeLocations(knowledgeId,{clientX:rect.right-220,clientY:rect.bottom+4})},{icon:'◫',label:'复制',action:()=>this.duplicateKnowledge(knowledgeId)},{icon:'↧',label:'导出',action:()=>{this.openKnowledge(knowledgeId);this.exportAs('markdown')}},{separator:true},{icon:'⌫',label:'删除知识…',danger:true,action:()=>this.deleteKnowledge(knowledgeId)}])}
