  deleteKnowledge(knowledgeId){const knowledge=this.state.knowledge.find(item=>item.id===knowledgeId);if(!knowledge)return;const impact=knowledgeDeletionImpact(this.state,knowledgeId),body=`<p>删除 <b>“${escapeHtml(knowledge.title)}”</b>？删除知识不等于仅解除当前位置的引用。</p><div class="impact-grid"><div class="impact-card"><b>${impact.ownedStructures.length}</b><small>个结构</small></div><div class="impact-card"><b>${impact.externalBindings.length}</b><small>个外部绑定</small></div><div class="impact-card"><b>${impact.relations.length}</b><small>个关系</small></div><div class="impact-card"><b>${impact.nestedReferences.length}</b><small>个嵌套引用</small></div></div><p>确认后可在当前会话使用撤销恢复。</p>`;this.showDangerDialog(`删除知识“${knowledge.title}”？`,body,'删除知识',()=>this.commit('knowledge:delete',()=>{deleteKnowledgeObject(this.state,knowledgeId);this.openDocuments.delete(knowledgeId);const next=this.state.knowledge[0];this.currentKnowledgeId=next?.id??null;this.currentInstanceId=next?this.state.structureInstances.find(item=>item.ownerKnowledgeId===next.id)?.id??null:null;this.document=next?(this.currentInstanceId?`structure:${this.currentInstanceId}`:'notes'):'welcome';this.path=next?[knowledgeSegment(next)]:[];this.selection.clear();this.closePanel()}))}
  openStructureMenu(instanceId,event){const rect=event.currentTarget.getBoundingClientRect(),instance=this.state.structureInstances.find(item=>item.id===instanceId),template=this.state.structureTemplates.find(item=>item.id===instance?.templateId),adapter=getStructureInteractionAdapter(template),items=[{icon:'✎',label:'重命名',action:()=>this.renameStructureInstance(instanceId)},{icon:'⚙',label:'设置',action:()=>{this.openInstance(instanceId);this.openPanel('structure',instanceId,'settings')}},{icon:'◐',label:'设计',action:()=>{this.openInstance(instanceId);this.openPanel('structure',instanceId,'design')}},{icon:'◫',label:'复制结构',action:()=>{this.openInstance(instanceId);this.duplicateCurrentInstance()}},{icon:'▣',label:'保存为模板',action:()=>{this.openInstance(instanceId);this.saveCurrentAsTemplate()}},{icon:'↧',label:'导出结构',action:()=>{this.openInstance(instanceId);this.exportAs('lkl')}}];if(adapter.id==='modular')items.splice(3,0,{icon:'ƒ',label:'变量',action:()=>{this.openInstance(instanceId);this.openPanel('structure',instanceId,'variables')}});if(template?.id==='builtin:lmn-432')items.push({icon:'⧉',label:'复制为自定义 LMN',action:()=>this.duplicateAsCustomLmnVariant(instanceId)});items.push({separator:true},{icon:'⌫',label:'删除结构…',danger:true,action:()=>this.deleteStructure(instanceId)});this.showContextMenu(rect.right-230,rect.bottom+4,items)}
  renameStructureInstance(instanceId){const instance=this.state.structureInstances.find(item=>item.id===instanceId),template=this.state.structureTemplates.find(item=>item.id===instance?.templateId);if(!instance)return;this.requestText('重命名结构',this.structureDisplayTitle(instance,template),name=>this.commit('structure:rename',()=>{instance.displayTitle=name;ensureObjectContent(instance,{contentType:'custom'}).title=name}),{label:'结构名称'})}
