  duplicateCurrentInstance(){if(!this.instance)return;let duplicate;this.commit('structure:duplicate',()=>{duplicate=cloneInstance(this.instance,this.currentKnowledgeId);this.state.structureInstances.push(duplicate);this.state.representations.push(createRepresentation(this.currentKnowledgeId,'structure',{instanceId:duplicate.id}));this.currentInstanceId=duplicate.id;this.document=`structure:${duplicate.id}`;this.rememberDocument(this.currentKnowledgeId,this.document);this.path=appendPath([knowledgeSegment(this.knowledge)],structureSegment(duplicate,this.template));this.fitPending=true});return duplicate}
